// Blank DOS 3.3 disk image (35 tracks x 16 sectors x 256 bytes, 143,360
// bytes), sourced from a known-good real reference disk (BLANKD.DSK) rather
// than synthesized from the format spec -- valid VTOC, fully linked empty
// catalog chain, track 0 reserved but tracks 1-2 left free/usable (this is
// NOT bootable DOS, just a properly INIT'd data disk, which is correct for
// a save disk: it's inserted while the machine is already running from the
// primary disk and never needs to boot on its own). The volume-number byte
// in the VTOC is patched per save-disk index so CATALOG shows a
// distinguishable volume number per disk.
const EMPTY_DISK_525 = "";

const VTOC_OFFSET = (0x11 * 16 + 0x00) * 256;
const VOLUME_NUMBER_OFFSET = VTOC_OFFSET + 0x06;

const createEmptyDisk525 = (index) => {
  const binaryString = atob(EMPTY_DISK_525);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  // Volume numbers are 1-254; wrap if more than 254 save disks are ever requested.
  bytes[VOLUME_NUMBER_OFFSET] = 1 + ((index - 1) % 254);
  return bytes;
}

export { createEmptyDisk525 }
